library ieee;use ieee.std_logic_1164.all;use ieee.numeric_std.all;entity tb_generic_counter_basic is end;architecture tb of tb_generic_counter_basic is signal clk:std_logic:='0';signal rst_n:std_logic:='0';signal en:std_logic:='1';signal clr:std_logic:='0';signal count:std_logic_vector(7 downto 0);signal term:std_logic;begin clk<=not clk after 5 ns;dut:entity work.generic_counter_basic generic map(G_WIDTH=>8,G_TERMINAL_VALUE=>3)port map(clk_i=>clk,rst_ni=>rst_n,enable_i=>en,clear_i=>clr,count_o=>count,terminal_o=>term);process begin wait for 12 ns;rst_n<='1';for i in 1 to 3 loop wait until rising_edge(clk);wait for 1 ns;end loop;assert unsigned(count)=3 severity error;wait until rising_edge(clk);wait for 1 ns;assert unsigned(count)=0 severity error;report "PASS" severity note;wait;end process;end;
